"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { 
    Upload, 
    X, 
    MapPin, 
    Crosshair, 
    Sparkles, 
    Loader2, 
    Eye,
    AlertCircle,
    Tag,
    FileText
} from "lucide-react";
import { Button } from "@/app/components/ui/button";
import { Input } from "@/app/components/ui/input";
import { Label } from "@/app/components/ui/label";
import { Card } from "@/app/components/ui/card";
import { Switch } from "@/app/components/ui/switch";
import { Badge } from "@/app/components/ui/badge";
import Header from "@/app/components/Header";
import Footer from "@/app/components/Footer";
import { addItem } from "@/app/lib/api";
import { toast } from "sonner";
import Image from "next/image";
import { useAuth } from "../context/AuthContext";
import ProductCard from "@/app/components/ProductCard";

export default function UploadPage() {
    const router = useRouter();
    const { isBuyerMode } = useAuth();
    const [loading, setLoading] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const [imagePreviews, setImagePreviews] = useState<string[]>([]);
    const [formData, setFormData] = useState({
        title: "",
        category: "",
        condition: "",
        price: "",
        content: "",
        location: "",
        images: [] as File[],
        allowBidding: true,
    });

    const categories = [
        "Electronics", "Fashion", "Home & Garden", "Sports", "Collectibles", "Vehicles", "Other"
    ];

    const conditions = ["New", "Like New", "Excellent", "Good", "Fair", "Poor"];

    const handleLocationFetch = () => {
        if (!navigator.geolocation) {
            toast.error("Geolocation is not supported by your browser");
            return;
        }

        toast.loading("Fetching your location...", { id: "location" });

        navigator.geolocation.getCurrentPosition(
            async (position) => {
                const { latitude, longitude } = position.coords;
                try {
                    const response = await fetch(
                        `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&addressdetails=1`
                    );
                    const data = await response.json();
                    
                    if (data.address) {
                        const addr = data.address;
                        const parts = [];

                        if (addr.amenity && addr.amenity !== addr.hospital) parts.push(addr.amenity);
                        if (addr.building) parts.push(addr.building);
                        if (addr.landmark) parts.push(addr.landmark);
                        if (addr.road) parts.push(addr.road);
                        if (addr.suburb) parts.push(addr.suburb);
                        else if (addr.neighbourhood) parts.push(addr.neighbourhood);
                        
                        if (addr.city) parts.push(addr.city);
                        else if (addr.town) parts.push(addr.town);

                        if (addr.state) parts.push(addr.state);

                        const formattedAddress = parts.filter(Boolean).join(", ");
                        setFormData(prev => ({ ...prev, location: formattedAddress }));
                        toast.success("Location updated!", { id: "location" });
                    }
                } catch (error) {
                    toast.error("Failed to fetch address", { id: "location" });
                }
            },
            () => toast.error("Geolocation access denied", { id: "location" })
        );
    };

    const handleGenerateDescription = async () => {
        if (!formData.title) return;

        setLoading(true);
        toast.loading("Generating description...", { id: "gen" });

        await new Promise(resolve => setTimeout(resolve, 1500));

        const title = formData.title.toLowerCase();
        const condition = formData.condition || "Excellent";
        const category = formData.category || "Item";

        let specs = "";
        if (title.includes("iphone") || title.includes("samsung") || title.includes("phone")) {
            specs = `\n\n✨ TECHNICAL SPECIFICATIONS:\n- Display: High Resolution OLED\n- RAM: 8GB Performance Booster\n- Storage: 128GB / 256GB Options\n- Camera: Professional Multi-lens System\n- Battery: Long-lasting Endurance`;
        } else if (title.includes("laptop") || title.includes("macbook")) {
            specs = `\n\n💻 TECHNICAL SPECIFICATIONS:\n- Processor: High-Speed Multi-core\n- RAM: 16GB Fast Memory\n- Storage: Quick NVMe SSD\n- Display: Crystal Clear Anti-glare`;
        }

        const templates = [
            `🚀 **FOR SALE: ${formData.title}** 🚀\n\nThis ${formData.title} is in ${condition} condition. It's a fantastic ${category} that offers great performance and value.${specs}\n\n🌟 HIGHLIGHTS:\n- Exceptional Quality\n- Sleek Design\n- 100% Functional\n\nDirect message me if interested!`,
            `🔥 **GREAT DEAL: ${formData.title}** 🔥\n\nSelling my ${formData.title} in ${condition} state. Perfect ${category} for daily use. Carefully maintained and ready for a new owner!${specs}\n\n💎 WHY BUY?\n- Reliable performance\n- Premium build\n- Verified condition\n\nPrice is slightly negotiable.`
        ];

        const description = templates[Math.floor(Math.random() * templates.length)];
        setFormData(prev => ({ ...prev, content: description }));
        toast.success("Description generated!", { id: "gen" });
        setLoading(false);

        setTimeout(() => {
            const textarea = document.getElementById("content") as HTMLTextAreaElement;
            if (textarea) {
                textarea.style.height = "auto";
                textarea.style.height = `${textarea.scrollHeight}px`;
            }
        }, 100);
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement> | FileList) => {
        const files = 'target' in e ? e.target.files : e;
        if (files) {
            const newFiles = Array.from(files);
            setFormData(prev => ({ ...prev, images: [...prev.images, ...newFiles] }));
            newFiles.forEach(file => {
                const reader = new FileReader();
                reader.onloadend = () => setImagePreviews(prev => [...prev, reader.result as string]);
                reader.readAsDataURL(file);
            });
        }
    };

    const removeImage = (index: number) => {
        const newImages = [...formData.images];
        newImages.splice(index, 1);
        const newPreviews = [...imagePreviews];
        newPreviews.splice(index, 1);
        setFormData({ ...formData, images: newImages });
        setImagePreviews(newPreviews);
    };

    const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
    const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault(); setIsDragging(false);
        if (e.dataTransfer.files.length > 0) handleImageChange(e.dataTransfer.files);
    };

    const getWordCount = (text: string) => text.trim().split(/\s+/).filter(Boolean).length;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (getWordCount(formData.content) > 999) {
            toast.error("Description too long (Max 999 words)");
            return;
        }
        if (formData.images.length === 0) {
            toast.error("Please upload at least one image");
            return;
        }

        setLoading(true);
        toast.loading("Listing item...", { id: "upload" });

        try {
            const data = new FormData();
            data.append("title", formData.title);
            data.append("content", formData.content);
            data.append("price", formData.price);
            data.append("location", formData.location);
            data.append("category", formData.category);
            data.append("condition", formData.condition);
            data.append("isBiddable", String(formData.allowBidding));
            formData.images.forEach(img => data.append("images", img));

            await addItem(data);
            toast.success("Item listed successfully!", { id: "upload" });
            router.push("/");
        } catch (error: any) {
            toast.error(error.message || "Failed to upload", { id: "upload" });
        } finally {
            setLoading(false);
        }
    };

    if (isBuyerMode) {
        return (
            <div className="min-h-screen bg-background flex flex-col">
                <Header />
                <main className="flex-1 container mx-auto px-4 py-16 text-center">
                    <Card className="max-w-md mx-auto p-8 space-y-4">
                        <AlertCircle className="h-12 w-12 text-yellow-500 mx-auto" />
                        <h1 className="text-2xl font-bold">Seller Mode Required</h1>
                        <p className="text-muted-foreground italic">Switch to Seller Mode in the header to upload.</p>
                        <Button onClick={() => router.push("/")} variant="outline" className="w-full">Home</Button>
                    </Card>
                </main>
                <Footer />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-background flex flex-col">
            <Header />
            <main className="flex-1 container mx-auto px-4 py-8">
                <div className="flex flex-col lg:flex-row gap-8">
                    <div className="flex-1 space-y-6">
                        <Card className="p-6 md:p-8 shadow-sm border">
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div className="space-y-4">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold flex items-center gap-2">
                                                <FileText className="h-4 w-4 text-primary" /> Title *
                                            </Label>
                                            <Input 
                                                placeholder="What are you selling?" 
                                                value={formData.title} 
                                                onChange={(e) => setFormData({...formData, title: e.target.value})} 
                                                required 
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold flex items-center gap-2">
                                                <MapPin className="h-4 w-4 text-primary" /> Location *
                                            </Label>
                                            <div className="relative">
                                                <Input 
                                                    placeholder="City, Area" 
                                                    value={formData.location} 
                                                    onChange={(e) => setFormData({...formData, location: e.target.value})} 
                                                    className="pr-10" 
                                                    required 
                                                />
                                                <button type="button" onClick={handleLocationFetch} className="absolute right-3 top-2.5 text-muted-foreground hover:text-primary">
                                                    <Crosshair className="h-4 w-4" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold">Price (Rs.) *</Label>
                                            <Input type="number" placeholder="0" value={formData.price} onChange={(e) => setFormData({...formData, price: e.target.value})} required />
                                        </div>
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold">Allow Bidding</Label>
                                            <div className="flex items-center gap-2 h-10">
                                                <Switch checked={formData.allowBidding} onCheckedChange={(c) => setFormData({...formData, allowBidding: c})} />
                                                <span className="text-xs text-muted-foreground">{formData.allowBidding ? "YES" : "NO"}</span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold">Category *</Label>
                                            <select value={formData.category} onChange={(e) => setFormData({...formData, category: e.target.value})} className="w-full h-10 rounded-md border border-input bg-background px-3 text-sm" required>
                                                <option value="">Select Category</option>
                                                {categories.map(c => <option key={c} value={c}>{c}</option>)}
                                            </select>
                                        </div>
                                        <div className="space-y-2">
                                            <Label className="text-sm font-semibold">Condition *</Label>
                                            <select value={formData.condition} onChange={(e) => setFormData({...formData, condition: e.target.value})} className="w-full h-10 rounded-md border border-input bg-background px-3 text-sm" required>
                                                <option value="">Select Condition</option>
                                                {conditions.map(c => <option key={c} value={c}>{c}</option>)}
                                            </select>
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center">
                                            <Label className="text-sm font-semibold">Description *</Label>
                                            <span className="text-[10px] text-muted-foreground uppercase">{getWordCount(formData.content)} / 999 WORDS</span>
                                        </div>
                                        <div className="relative">
                                            <textarea
                                                id="content"
                                                placeholder="Describe your item..."
                                                value={formData.content}
                                                onChange={(e) => {
                                                    setFormData({...formData, content: e.target.value});
                                                    e.target.style.height = "auto";
                                                    e.target.style.height = `${e.target.scrollHeight}px`;
                                                }}
                                                className="w-full min-h-[56px] px-3 py-2 text-sm rounded-md border border-input bg-background focus:ring-1 focus:ring-primary outline-none transition-all"
                                                required
                                            />
                                            <Button type="button" onClick={handleGenerateDescription} disabled={!formData.title || loading} size="sm" className="absolute right-2 bottom-2 h-7 px-2 text-[10px] font-bold">
                                                <Sparkles className="h-3 w-3 mr-1" /> GENERATE
                                            </Button>
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <Label className="text-sm font-semibold">Photos *</Label>
                                        <div 
                                            onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}
                                            className={`grid grid-cols-4 gap-4 p-4 rounded-xl border-2 border-dashed transition-all ${isDragging ? 'border-primary bg-primary/5 scale-[1.01]' : 'border-muted-foreground/20'}`}
                                        >
                                            {imagePreviews.map((p, i) => (
                                                <div key={i} className="relative aspect-square rounded-lg overflow-hidden border">
                                                    <Image src={p} alt="preview" fill className="object-cover" />
                                                    <button type="button" onClick={() => removeImage(i)} className="absolute top-1 right-1 bg-black/60 text-white rounded-full p-1"><X className="h-3 w-3" /></button>
                                                </div>
                                            ))}
                                            <label className="flex flex-col items-center justify-center aspect-square border-2 border-dashed rounded-lg cursor-pointer hover:bg-muted/50 transition-colors">
                                                <input type="file" multiple accept="image/*" onChange={handleImageChange} className="hidden" />
                                                <Upload className="h-6 w-6 text-muted-foreground" />
                                                <span className="text-[10px] font-bold mt-1 uppercase">Upload</span>
                                            </label>
                                        </div>
                                    </div>
                                </div>
                                <Button type="submit" className="w-full h-12 text-lg font-bold shadow-lg shadow-primary/20" disabled={loading}>
                                    {loading ? <Loader2 className="animate-spin" /> : "LIST ITEM NOW"}
                                </Button>
                            </form>
                        </Card>
                    </div>

                    <div className="w-full lg:w-[380px]">
                        <div className="sticky top-24 space-y-4">
                            <h2 className="text-xl font-bold flex items-center gap-2"><Eye className="h-5 w-5 text-primary" /> Live Preview</h2>
                            <div className="max-w-sm mx-auto">
                                <ProductCard
                                    title={formData.title || "Item Title"}
                                    price={Number(formData.price) || 0}
                                    image={imagePreviews[0] || ""}
                                    location={formData.location || "Location"}
                                    timePosted="Just now"
                                    isBiddable={formData.allowBidding}
                                    showEdit={false}
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </main>
            <Footer />
        </div>
    );
}
